import sys
from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        edges.append((u - 1, v - 1))  # 0-indexed

    # Find connected components
    parent = list(range(n))
    size = [1] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[py] = px
            size[px] += size[py]

    for u, v in edges:
        union(u, v)

    # Get component sizes (only unique sizes with their counts)
    compSizes = [size[i] for i in range(n) if parent[i] == i]

    # Generate all lucky numbers <= n
    def generate_lucky_numbers():
        lucky_nums = set()
        def gen(current):
            if current > n:
                return
            if current > 0:
                lucky_nums.add(current)
            gen(current * 10 + 4)
            gen(current * 10 + 7)
        gen(0)
        return sorted(lucky_nums)

    lucky_nums = generate_lucky_numbers()

    # Check if current components already have a lucky size
    for s in compSizes:
        if s in lucky_nums:
            return "0\n"

    # Frequency dictionary for component sizes
    freq = defaultdict(int)
    for s in compSizes:
        freq[s] += 1

    # Generate all unique component sizes
    unique_sizes = list(freq.keys())

    num_unique = len(unique_sizes)

    # Use dynamic programming to check if each lucky number is achievable
    min_roads = {}

    def can_form(target, used_count):
        # Returns (is_achievable, min_used_components)
        @lru_cache(None)  # memoization but need to clear per target
        def dp(index, remaining):
            if remaining == 0:
                return True, 0
            if index == num_unique:
                return False, float('inf')

            s = unique_sizes[index]
            count = freq[s]

            # Option 1: don't use this size
            res1, used1 = dp(index + 1, remaining)

            # Option 2: use this size up to available count
            best_res, best_used = False, float('inf')
            for use in range(1, count + 1):
                if use * s <= remaining:
                    res2, used2 = dp(index + 1, remaining - use * s)
                    res = res2 and used2 != float('inf')
                    if res and used + use < best_used:
                        best_used = used + use
                    if res:
                        if not res1 or used + use < used1:
                            best_res, best_used = res, best_used

            if res1:
                if best_res or res1:
                    total_used = min(used1, best_used) if best_used != float('inf') else used1
                    return True, total_used

            return best_res, best_used

        return dp(0, target)

    # For efficiency, use a simpler BFS/DP approach
    # dp[i] = min components needed to form size i
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    # Process each unique size
    for s in unique_sizes:
        count = freq[s]
        for i in range(count):
            for target in range(s, n + 1):
                if dp[target - s] != float('inf'):
                    dp[target] = min(dp[target], dp[target - s] + 1)

    # Find minimum roads to form any lucky number
    ans = float('inf')
    for v in dp:
        if v <= 0.5:  # 0 means already formed
            ans = min(ans, 0)

    for lucky in lucky_nums:
        if dp[lucky] != float('inf'):
            roads = dp[lucky] - 1
            ans = min(ans, roads)
            if ans == 0:
                break

    if ans == float('inf'):
        return "-1\n"
    else:
        return f"{ans}\n"

