    lines = input_string.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Precompute Grundy numbers
    # Based on analysis, we need to find a pattern
    # For large ai (up to 10^9), we need per-case computation

    def get_grundy(n, k):
        # Compute Grundy number for pile size n, parameter k
        # This needs memoization for efficiency
        memo = {}

        def compute_grundy(val):
            if val == 0:
                return 0
            if val in memo:
                return memo[val]

            # Option 1: remove 1 cow
            options = {compute_grundy(val - 1)}

            # Option 2: if even, split into k piles of val//2 each
            if val % 2 == 0:
                half = val // 2
                # XOR of k copies of g(half)
                g_half = compute_grundy(half)
                if k % 2 == 0:
                    xor_val = 0 if k % 2 == 0 else g_half
                else:
                    xor_val = g_half
                options.add(xor_val)

            # Find mex
            mex = 0
            while mex in options:
                mex += 1
            memo[val] = mex
            return mex

        return compute_grundy(n)

    # For better performance, we need to detect patterns
    # Let's compute a few values to find the pattern
    max_val = max(a)

    memo = {}

    def compute(val):
        if val == 0:
            return 0
        if val in memo:
            return memo[val]

        if val % 2 != 0:
            # For odd numbers, only move is remove 1
            memo[val] = compute(val - 1)
        else:
            # For even numbers
            options = {compute(val - 1)}
            half = val // 2
            g_half = compute(half)
            # XOR of k copies
            if k % 2 == 0:
                options.add(0)  # Even XOR sum is identity
            else:
                options.add(g_half)

            mex = 0
            while mex in options:
                mex += 1
            memo[val] = mex

        return memo[val]

    # Compute XOR sum of all piles
    xor_sum = 0
    for x in a:
        xor_sum ^= compute(x)

    if xor_sum != 0:
        return "Kevin\n"
    else:
        return "Nicky\n"

