def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    def is_gp(seq):
        n = len(seq)
        if n <= 2:
            return True

        # If first element is 0
        if seq[0] == 0:
            # For a GP starting with 0, all must be 0
            return all(x == 0 for x in seq)

        # For a GP with non-zero first element
        a = seq[0]
        ap1 = seq[1]

        if ap1 == 0:
            # Then ratio is 0, so all remaining must be 0
            return all(x == 0 for x in seq[2:])

        # Use cross-multiplication to avoid floating point issues
        # Check if seq[i] * a == seq[i-1] * ap1 for all i
        for i in range(2, n):
            if seq[i] * a != seq[i-1] * ap1:
                return False
        return True

    # Check if already GP
    if is_gp(arr):
        return '0\n'

    # Try removing each element
    for i in range(n):
        test_arr = arr[:i] + arr[i+1:]
        if is_gp(test_arr):
            return '1\n'

    return '2\n'

