def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    from collections import defaultdict

    # Factorize each number into prime exponents
    # prime_counts[prime][position] = exponent of prime at position (0-indexed)
    prime_counts = defaultdict(lambda: defaultdict(int))

    for i in range(n):
        num = a[i]
        d = 2
        while d * d <= num and num > 1:
            while num % d == 0:
                prime_counts[d][i] += 1
                num //= d
            d += 1
        if num > 1:
            prime_counts[num][i] += 1

    # Separate prime counts by odd (1-indexed) and even (1-indexed) positions
    odd_sum = defaultdict(int)
    even_sum = defaultdict(int)

    for i in range(n):
        pos = i + 1  # Convert to 1-indexed position
        if pos % 2 == 1:  # Odd position (1, 3, 5, ...)
            for p, count in prime_counts[i].items():
                odd_sum[p] += count
        else:  # Even position (2, 4, 6, ...)
            for p, count in prime_counts[i].items():
                even_sum[p] += count

    # For each prime, we can extract min(odd_sum[p], even_sum[p]) operations
    # because each operation removes one occurrence from both odd and even side
    all_primes = set(odd_sum.keys()) | set(even_sum.keys())
    total_ops = 0

    for p in all_primes:
        if odd_sum[p] > 0 and even_sum[p] > 0:
            total_ops += min(odd_sum[p], even_sum[p])

    return str(total_ops) + '\n'

