def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    strengths = list(map(int, lines[1].split()))
    m = int(lines[3])
    actions = []

    for i in range(m):
        parts = lines[4 + i].split()
        actions.append((parts[0], int(parts[1])))

    memo = {}

    def solve(action_idx, available):
        # Base case: all actions completed
        if action_idx == m:
            return 0

        # Create memoization key
        key = (action_idx, frozenset(available))
        if key in memo:
            return memo[key]

        action_type, team = actions[action_idx]
        result = 0

        if action_type == 'p':
            # Pick action
            if team == 1:
                # Team 1 wants to maximize the difference (team1 - team2)
                result = max(strong[hero] + solve(action_idx + 1, available - {hero}) 
                           for hero in available)
                strong = strengths
            else:
                # Team 2 wants to minimize the difference (team1 - team2)
                # This is equivalent to maximizing (team2 - team1)
                result = max(-strengths[hero] + solve(action_idx + 1, available - {hero}) 
                           for hero in available)
        else:
            # Ban action
            # Team 1 wants to ban hero that maximizes remaining advantage
            # Team 2 wants to ban hero that minimizes remaining disadvantage
            # Both want to maximize their optimal result
            if team == 1:
                result = max(solve(action_idx + 1, available - {hero}) 
                           for hero in available)
            else:
                result = max(solve(action_idx + 1, available - {hero}) 
                           for hero in available)

        memo[key] = result
        return result

    return str(solve(0, set(range(n)))) + '\n'


