            s = str(num).zfill(n)
            chars = []
            for i, ch in enumerate(s):
                vec = int(ch)
                chars.append(mappings[i][vec])
            return "".join(chars)

        max_diff = 0
        end_num = start + max_diff + 1

        def check(start, other, t):
            enc_start = get_encodings(start, t)
            enc_other = get_encodings(other, t)
            return enc_start == enc_other

        limit = 0
        for other in range(start + 1, 10**n):
            is_cousin = False
            limit = max(limit, other)
            if check(start, other, 0):
                is_cousin = True
                for t in range(50):
                    if t > 10**n - 1:
                        is_cousin = False
                        break
                    non_cousin = check(start, other, t)
