def solution(input_str):
    """
    Solves the problem of finding the minimum budget to disconnect towns s and t
    by removing at most 2 roads.

    Args:
        input_str: A string containing the problem input

    Returns:
        A string containing the output with minimum budget, number of closed roads,
        and their indices.
    """
    data = input_str.strip().split()
    if not data:
        return "-1"

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1
    s = int(data[idx]); idx += 1
    t = int(data[idx]); idx += 1

    edges = []
    for i in range(1, m + 1):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        w = int(data[idx]); idx += 1
        edges.append({'u': u, 'v': v, 'w': w, 'id': i})

    def is_connected(excluded_ids):
        """Check if there exists a path from s to t avoiding excluded edges."""
        if not excluded_ids:
            excluded_ids = set()
        else:
            excluded_ids = set(excluded_ids)

        graph_adj = [[] for _ in range(n + 1)]
        for e in edges:
            if e['id'] not in excluded_ids:
                graph_adj[e['u']].append(e['v'])
                graph_adj[e['v']].append(e['u'])

        visited = {s}
        queue = deque([s])

        while queue:
            u = queue.popleft()
            if u == t:
                return True
            for v in graph_adj[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)

        return False

    # Check 0 edges (already disconnected)
    if not is_connected(set()):
        return "0\n0\n"

    # Check 1 edge
    min_cost = float('inf')
    best_1 = None

    for edge in edges:
        if not is_connected({edge['id']}):
            if edge['w'] < min_cost:
                min_cost = edge['w']
                best_1 = [edge['id']]

    if best_1 is not None:
        return f"{min_cost}\n1\n{' '.join(map(str, sorted(best_1)))}\n"

    # Check 2 edges
    min_cost2 = float('inf')
    best_2 = None

    for i in range(len(edges)):
        for j in range(i + 1, len(edges)):
            if not is_connected({edges[i]['id'], edges[j]['id']}):
                cost = edges[i]['w'] + edges[j]['w']
