import collections

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or lines[0] == '':
        return "IMPOSSIBLE"

    n, c = map(int, lines[0].split())

    constraints = []
    for i in range(1, c + 1):
        parts = lines[i].split()
        if len(parts) >= 3:
            a = int(parts[0])
            b = int(parts[1])
            direction = parts[2]
            constraints.append((a, b, direction))

    # If no nodes, impossible
    if n == 0:
        return "IMPOSSIBLE"

    # If no constraints, any valid tree works (just output 1 to n)
    if c == 0:
        return ' '.join(map(str, range(1, n + 1))) + ' '

    # If node is forced to be both left and right child of same parent, impossible
    for a, b, _ in constraints:
        if a == b:
            return "IMPOSSIBLE"

    # Build dependency graph
    # LEFT(a,b): b must come before a in ordering
    # RIGHT(a,b): a must come before b in ordering
    graph = collections.defaultdict(list)
    in_degree = collections.defaultdict(int)

    for a, b, direction in constraints:
        if direction == 'LEFT':
            # b -> a (b comes before a)
            graph[b].append(a)
            in_degree[a] += 1
        else:
            # a -> b (a comes before b)
            graph[a].append(b)
            in_degree[b] += 1

    # Topological sort using Kahn's algorithm
    queue = collections.deque([i for i in range(1, n + 1) if 1 <= i <= n and in_degree.get(i, 0) == 0])
    result = []

    while queue:
        node = queue.popleft()
        result.append(node)

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If result doesn't contain all nodes, there's a cycle (IMPOSSIBLE)
    if len(result) != n:
        return "IMPOSSIBLE"

    # Verify the result satisfies all constraints
    for a, b, direction in constraints:
        if direction == 'LEFT':
            # b should be in left subtree of a, so b comes before a
            if result.index(b) >= result.index(a):
                return "IMPOSSIBLE"
        else:
            # b should be in right subtree of a, so a comes before b
            if result.index(a) >= result.index(b):
                return "IMPOSSIBLE"

    return ' '.join(map(str, result)) + ' '

def solution(input_str):
    n, x = map(int, input_str.strip().split())

    if n == 1:
        return "-1"

    # Start from x-1 and check for prime b where (b-1) % n == 0
    b = x - 1
    while b > 2:
        if (b - 1) % n == 0:
            # Check if b is prime
            if b < 2:
                b -= 1
                continue
            is_prime = True
            for i in range(2, int(b**0.5) + 1):
                if b % i == 0:
                    is_prime = False
                    break
            if is_prime:
                return str(b)
        b -= 1

    return "-1"

