def solution(s):
    parts = s.strip().split('\n')
    n = int(parts[0])
    a = list(map(int, parts[1].split()))

    total_sum = sum(a)

    if total_sum == 0:
        return "-1\n"

    if n == 1:
        if total_sum < 2:
            return "-1\n"
        return "0\n"

    # Find all divisors of total_sum > 1
    divisors = []
    i = 1
    while i * i <= total_sum:
        if total_sum % i == 0:
            divisors.append(i)
            if i != total_sum // i:
                divisors.append(total_sum // i)
        i += 1

    min_cost = float('inf')

    for k in divisors:
        if k == 1:
            continue

        cost = 0
        rem = 0
        # For each position except the last one
        for j in range(n - 1):
            rem = (rem + a[j]) % k
            # We can either move 'rem' items to the right or 'k-rem' items to the left
            cost += min(rem, k - rem)

        if cost < min_cost:
            min_cost = cost

    if min_cost == float('inf'):
        return "-1\n"
    return f"{min_cost}\n"

