from typing import List

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def get_prime_factors(n: int) -> set:
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors.add(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def is_pairwise_coprime(seq: List[int]) -> bool:
    for i in range(len(seq)):
        for j in range(i + 1, len(seq)):
            if gcd(seq[i], seq[j]) != 1:
                return False
    return True

def calculate_cost(a: List[int], b: List[int]) -> int:
    """Calculate the cost function to minimize."""
    cost = 0
    for i in range(len(a)):
        b_i = b[i]
        if b_i == 1:
            cost += 1
        else:
            cost += gcd(a[i], b_i) + math.gcd(b_i, a[i] + 1)
    # Simpler interpretation - each pair contributes
    for i in range(len(a)):
        for j in range(i + 1, len(a)):
            if gcd(b[i], b[j]) == 1:
                cost += 1
    # Accumulate a[i] contributions when coprime
    for i in range(len(a)):
        for j in range(i + 1, len(a)):
            cost += gcd(a[i], a[j])
    return cost

