            for j in range(i * i, 101, i):
                is_prime[j] = False
    candidates.update(primes)

    best_b = None
    best_cost = float('inf')

    # Greedy approach: for each position, pick a number that minimizes cost
    # while maintaining pairwise coprimality
    def try_solve(idx: int, current_b: List[int], used_factor: set) -> List[int]:
        nonlocal best_b, best_cost

