    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        coords.append((x, y))

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def on_segment(p, a, b):
        return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and
                min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

    def segments_intersect(p1, q1, p2, q2):
        d1 = cross_product(p2, q2, p1)
        d2 = cross_product(p2, q2, q1)
        d3 = cross_product(p1, q1, p2)
        d4 = cross_product(p1, q1, q2)

        if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
           ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
            return True

        if d1 == 0 and on_segment(p1, p2, q2):
            return True
        if d2 == 0 and on_segment(q1, p2, q2):
            return True
        if d3 == 0 and on_segment(p2, p1, q1):
            return True
        if d4 == 0 and on_segment(q2, p1, q1):
            return True

        return False

    def is_diagonal_interior(i, j):
        if j == i + 1:
            return True
        if i == 0 and j == n - 1:
            return True

        for k in range(n):
            next_k = (k + 1) % n
            if segments_intersect(coords[i], coords[j], coords[k], coords[next_k]):
                return False

        return True

    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][(i + 1) % n] = 1

    for length in range(3, n + 1):
        for i in range(n):
            j = (i + length) % n
            if j < i:
                continue
            for k in range(i + 1, j + 1):
