                    continue
                if is_diagonal_interior(i, k) and is_diagonal_interior(k, j):
                    dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

    result = dp[0][n - 1]
    return str(result) + "\n"

