        for r in range(n):
            row = list(map(int, lines[idx].split()))
            idx += 1
            matrix.append(row)

        ops = lines[idx]
        idx += 1

        # Convert to 0-indexed internally
        for r in range(n):
            matrix[r] = [x - 1 for x in matrix[r]]

        # Process each operation
        for op in ops:
            if op == 'R':
                # Shift columns right: col 0 becomes old col n-1, col 1 becomes old col 0
                for r in range(n):
                    matrix[r] = [matrix[r][n-1]] + matrix[r][:n-1]
            elif op == 'L':
                # Shift columns left: col 0 becomes old col 1, last col becomes old col 0
                for r in range(n):
                    matrix[r] = matrix[r][1:] + [matrix[r][0]]
            elif op == 'D':
                # Shift rows down: row 0 becomes old row n-1, others shift up
                first = matrix[0]
                for r in range(1, n):
                    matrix[r-1] = matrix[r]
                matrix[n-1] = first
            elif op == 'U':
                # Shift rows up: row 0 becomes old row 1, last becomes old row 0
                last = matrix[n-1]
                for r in range(n-1, 0, -1):
                    matrix[r] = matrix[r-1]
                matrix[0] = last
            elif op == 'I':
                # Inverse each row permutation
                for r in range(n):
                    inv = [0] * n
                    for c in range(n):
                        val = matrix[r][c]  # val = value at position c (0-indexed)
                        # Inverse: value at position val gets position c+1 (0-indexed as c)
                        inv[val] = c
                    matrix[r] = inv
            elif op == 'C':
                # Inverse each column permutation
                for c in range(n):
                    col = [matrix[r][c] for r in range(n)]
                    inv = [0] * n
                    for r in range(n):
                        val = col[r]
                        inv[val] = r
                    for r in range(n):
                        matrix[r][c] = inv[r]

        # Convert back to 1-indexed for output
        for r in range(n):
            output_lines.append(' '.join(map(str, [x + 1 for x in matrix[r]])) + ' ')

    output_lines.append('')  # Separate test cases
    return '\n'.join(output_lines)

