    n = int(parts[0])
    m = int(parts[1])

    swapLR = int(parts[2]) if len(parts) >= 3 else 0
    swapUD = int(parts[3]) if len(parts) >= 4 else 0

    grid = lines[1:n + 1]

    # Find finish
    finish = None
    for i in range(n):
        if i < len(grid):
            for j in range(m):
                if j < len(grid[i]) and grid[i][j] == 'F':
                    finish = (i, j)
                    break
        if finish:
            break

    if not finish:
        return ""

    start = (0, 0)

    # BFS for shortest path
    queue = deque([(start[0], start[1], "")])
    visited = {start}
    directions = [
        ('U', -1, 0), ('D', 1, 0), ('L', 0, -1), ('R', 0, 1)
    ]

    while queue:
        r, c, path = queue.popleft()

        if (r, c) == finish:
            return path

        for cmd, dr, dc in directions:
            # Swap directions if needed
            if cmd == 'L' and swapLR:
                dr, dc = 0, 1
            elif cmd == 'R' and swapLR:
                dr, dc = 0, -1
            elif cmd == 'U' and swapUD:
                dr, dc = 1, 0
            elif cmd == 'D' and swapUD:
                dr, dc = -1, 0

